    # Improve mixed-language typography without modifying stable identifiers or URLs.
    import re
    def readable(v,key=''):
        if isinstance(v,dict):return {k:readable(x,k) for k,x in v.items()}
        if isinstance(v,list):return [readable(x,key) for x in v]
        if not isinstance(v,str) or key in ['id','slug','url','source','status','checked','start','end','iso','language_evidence_role']:return v
        v=re.sub(r'([А-Яа-яЁё])([A-Za-z])',r'\1 \2',v)
        v=re.sub(r'([A-Za-z])([А-Яа-яЁё])',r'\1 \2',v)
        v=re.sub(r'([A-Za-zА-Яа-яЁё])(\d)',r'\1 \2',v)
        v=re.sub(r'(\d)([A-Za-zА-Яа-яЁё])',r'\1 \2',v)
        v=re.sub(r'([а-яё])([А-ЯA-ZЁ])',r'\1 \2',v)
        return re.sub(r'([,;])(?=\S)',r'\1 ',v)
    for i,p in enumerate(profiles):
        if p['slug'] in NEW:profiles[i]=readable(p)

